const item = $input.item.json;
const c = item.config;
const b = item.body || {};
const errors = [];
if (!item.headers || item.headers['x-qualifier-token'] !== c.internalToken) errors.push('bad_token');
if (!Number.isInteger(b.outbox_id)) errors.push('outbox_id');
return { json: { request: { outbox_id: b.outbox_id }, validation: { ok: errors.length === 0, errors }, config: c } };

const s = $('Validate Request').item.json;
const row = $input.item.json.outbox_id ? $input.item.json : null;
let reason = null;
if (!row) reason = 'no_outbox_row';
else if (row.suppressed || row.state_status === 'dnc') reason = 'suppressed';
else if (row.outbox_status !== 'pending') reason = 'outbox_' + row.outbox_status;
else if (row.kind === 'followup' && row.state_status !== 'active') reason = 'conversation_not_active';
const message = row ? { id: Number(row.outbox_id), contact_id: row.contact_id, kind: row.kind, body: row.body } : null;
const contact = row ? { contact_id: row.contact_id, name: row.name, phone: row.phone, email: row.email, timezone: row.timezone } : null;
return { json: { ...s, message, contact, guard: { ok: reason === null, reason, row: row ? { outbox_status: row.outbox_status, state_status: row.state_status, suppressed: row.suppressed } : null } } };

const { inferTimezone, isWithinWindow, nextWindowOpen } = (() => {
  const module = { exports: {} };
// Horario de envío: determinístico. Un mensaje comercial solo sale en horario laboral LOCAL del contacto.
// Si no sabemos su zona horaria, usamos la de por defecto y lo declaramos (source: 'default'): nunca se asume en silencio.
const TZ_BY_CALLING_CODE = [
  ['+57', 'America/Bogota'], ['+52', 'America/Mexico_City'], ['+34', 'Europe/Madrid'], ['+44', 'Europe/London'],
  ['+54', 'America/Argentina/Buenos_Aires'], ['+56', 'America/Santiago'], ['+51', 'America/Lima'], ['+593', 'America/Guayaquil'],
  // '+1' se omite a propósito: abarca varias zonas horarias; sin código de área fiable caemos a la zona por defecto.
];

function isValidTimezone(tz) {
  if (typeof tz !== 'string' || !tz) return false;
  try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch { return false; }
}

const WEEKDAYS = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };

// Día ISO (1=lunes..7=domingo), hora y minuto del instante dado en la zona indicada.
function localParts(nowIso, tz) {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short', hour: 'numeric', minute: 'numeric', hourCycle: 'h23' }).formatToParts(new Date(nowIso));
  const get = type => parts.find(p => p.type === type).value;
  return { weekday: WEEKDAYS[get('weekday')], hour: Number(get('hour')), minute: Number(get('minute')) };
}

// startHour incluida, endHour excluida.
function isWithinWindow(nowIso, tz, window) {
  const { weekday, hour } = localParts(nowIso, tz);
  return window.weekdays.includes(weekday) && hour >= window.startHour && hour < window.endHour;
}

// Primer instante (resolución de 15 min) en que la ventana está abierta; el mismo instante si ya lo está.
// null si en 8 días no abre nunca (configuración sin días laborales).
function nextWindowOpen(nowIso, tz, window) {
  if (!window.weekdays.length) return null;
  const STEP = 15 * 60 * 1000;
  let t = Math.ceil(Date.parse(nowIso) / STEP) * STEP;
  if (isWithinWindow(nowIso, tz, window)) return new Date(Date.parse(nowIso)).toISOString();
  for (let i = 0; i < 8 * 24 * 4; i++, t += STEP) {
    const iso = new Date(t).toISOString();
    if (isWithinWindow(iso, tz, window)) return iso;
  }
  return null;
}

function inferTimezone(contact, cfg) {
  if (isValidTimezone(contact.timezone)) return { tz: contact.timezone, source: 'contact' };
  const phone = typeof contact.phone === 'string' ? contact.phone.replace(/[^\d+]/g, '') : '';
  if (phone.startsWith('+')) {
    const hit = [...TZ_BY_CALLING_CODE].sort((a, b) => b[0].length - a[0].length).find(([code]) => phone.startsWith(code));
    if (hit) return { tz: hit[1], source: 'phone' };
  }
  return { tz: cfg.defaultTimezone, source: 'default' };
}

const DAY_NAMES = ['', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const pad = n => String(n).padStart(2, '0');

// "Thu 09:00" en la zona del contacto.
function describeLocal(iso, tz) {
  const p = localParts(iso, tz);
  return `${DAY_NAMES[p.weekday]} ${pad(p.hour)}:${pad(p.minute)}`;
}

// Texto para el dueño: ¿sale ya o se retiene? Si la zona es la de por defecto, lo dice (es una suposición).
function sendNote(nowIso, tzInfo, window) {
  const range = `${pad(window.startHour)}:00-${pad(window.endHour)}:00 local, ${tzInfo.tz}`;
  const assumed = tzInfo.source === 'default' ? ' Time zone assumed (not known for this contact).' : '';
  if (isWithinWindow(nowIso, tzInfo.tz, window)) return `Sends right away (sending hours ${range}).${assumed}`;
  const next = nextWindowOpen(nowIso, tzInfo.tz, window);
  return next ? `Held until ${describeLocal(next, tzInfo.tz)} local (sending hours ${range}).${assumed}` : `No sending hours are configured.${assumed}`;
}

module.exports = { isValidTimezone, localParts, isWithinWindow, nextWindowOpen, inferTimezone, describeLocal, sendNote };

  return module.exports;
})();

const s = $input.item.json;
const info = inferTimezone({ timezone: s.contact.timezone, phone: s.contact.phone }, s.config);
const now = new Date().toISOString();
const transactional = s.message.kind === 'confirmation';
const open = transactional || isWithinWindow(now, info.tz, s.config.sendWindow);
const next = open ? null : nextWindowOpen(now, info.tz, s.config.sendWindow);
return { json: { ...s, window: { open, transactional, tz: info.tz, source: info.source, now, next, no_window: !open && next === null } } };

const s = $('Check Window').item.json;
const r = $input.item.json;
return { json: { ...s, idem: { key: r.key, is_new: r.is_new === true } } };

const s = $('Send Mode?').item.json;
const r = $input.item.json;
return { json: { ...s, send: r.error ? { ok: false, mode: 'mock', error: JSON.stringify(r.error) } : { ok: true, mode: 'mock' } } };

const { retryDecision } = (() => {
  const module = { exports: {} };
// Determinístico: decide si una llamada HTTP fallida se reintenta y cuánto esperar (backoff exponencial con jitter).
// n8n solo trae espera fija por nodo; el crecimiento exponencial lo da el bucle Check → Wait → reintento.
function statusOf(error) {
  const raw = error.httpCode ?? error.status ?? (error.cause && error.cause.status) ?? (error.response && error.response.status);
  if (raw !== undefined && raw !== null && !Number.isNaN(Number(raw))) return Number(raw);
  const m = /^\s*(\d{3})\b/.exec(String(error.message || ''));
  return m ? Number(m[1]) : null;
}

// attempt = número (1-based) del intento que acaba de terminar.
function retryDecision(resp, attempt, opts = {}) {
  const { maxAttempts = 4, baseSeconds = 2, capSeconds = 60, random = Math.random } = opts;

  const isNil = resp === undefined || resp === null;
  if (!isNil && !resp.error) return { retry: false, failed: false, exhausted: false, status: null, delay_s: 0, attempt, reason: 'ok' };

  const error = isNil ? { message: 'empty response' } : (typeof resp.error === 'object' ? resp.error : { message: String(resp.error) });
  const status = statusOf(error);
  const retryable = status === null || status === 408 || status === 425 || status === 429 || status >= 500;

  if (!retryable) return { retry: false, failed: true, exhausted: false, status, delay_s: 0, attempt, reason: `non-retryable status ${status}` };
  if (attempt >= maxAttempts) return { retry: false, failed: true, exhausted: true, status, delay_s: 0, attempt, reason: `retries exhausted after ${attempt} attempts (status ${status ?? 'network'})` };

  const exp = Math.min(capSeconds, baseSeconds * 2 ** (attempt - 1));
  const delay_s = Math.round(exp * (0.5 + 0.5 * random()) * 10) / 10;
  return { retry: true, failed: false, exhausted: false, status, delay_s, attempt, reason: `retryable status ${status ?? 'network'}` };
}

module.exports = { retryDecision };

  return module.exports;
})();

const state = $('Send Mode?').item.json;
const http = retryDecision($input.item.json, $runIndex + 1, { maxAttempts: 4 });
return { json: { ...state, http_response: $input.item.json, http } };

parameters.query:
WITH o AS (
  UPDATE qualifier_outbox SET status = 'sent', sent_at = now(), tz = $3, tz_source = $4, execution_id = $5 WHERE id = $1 AND status = 'pending' RETURNING id
), m AS (
  INSERT INTO messages_log (message_id, contact_id, direction, body, execution_id) VALUES ('out:' || $1, $2, 'out', $6, $5) ON CONFLICT (message_id) DO NOTHING RETURNING id
), st AS (
  UPDATE conversation_state SET last_outbound_at = now(), updated_at = now(),
    followup_sent_at = CASE WHEN $7 = 'followup' THEN now() ELSE followup_sent_at END
  WHERE contact_id = $2 RETURNING contact_id
)
SELECT (SELECT count(*) FROM o) AS outbox_rows, (SELECT count(*) FROM m) AS log_rows, (SELECT count(*) FROM st) AS state_rows

